// Object keywords: properties, patternProperties, additionalProperties,
// required, dependencies, propertyNames, maxProperties, minProperties.
//
// All of these apply only when the instance is an object; for any other
// instance type they yield no errors (mirroring jsonschema's guards).

import { ValidationError } from '../errors.mjs';

export function* properties(validator, value, instance, schema) {
  if (!validator.isType(instance, 'object')) return;
  for (const [property, subschema] of Object.entries(value)) {
    if (Object.prototype.hasOwnProperty.call(instance, property)) {
      yield* validator.descend(instance[property], subschema, property);
    }
  }
}

export function* patternProperties(validator, value, instance, schema) {
  if (!validator.isType(instance, 'object')) return;
  for (const [pattern, subschema] of Object.entries(value)) {
    const re = new RegExp(pattern, 'u');
    for (const [k, v] of Object.entries(instance)) {
      if (re.test(k)) {
        yield* validator.descend(v, subschema, k);
      }
    }
  }
}

export function* additionalProperties(validator, value, instance, schema) {
  if (!validator.isType(instance, 'object')) return;

  const declared =
    schema.properties !== null && typeof schema.properties === 'object'
      ? schema.properties
      : {};
  const patterns =
    schema.patternProperties !== null &&
    typeof schema.patternProperties === 'object'
      ? Object.keys(schema.patternProperties).map((p) => new RegExp(p, 'u'))
      : [];

  const extras = Object.keys(instance).filter(
    (property) =>
      !Object.prototype.hasOwnProperty.call(declared, property) &&
      !patterns.some((re) => re.test(property))
  );

  if (value === false) {
    for (const extra of extras) {
      yield new ValidationError(
        `Additional properties are not allowed (${JSON.stringify(extra)} was unexpected)`
      );
    }
  } else if (value !== true) {
    for (const extra of extras) {
      yield* validator.descend(instance[extra], value, extra);
    }
  }
}

export function* required(validator, value, instance, schema) {
  if (!validator.isType(instance, 'object')) return;
  for (const name of value) {
    if (!Object.prototype.hasOwnProperty.call(instance, name)) {
      yield new ValidationError(`${JSON.stringify(name)} is a required property`);
    }
  }
}

export function* dependencies(validator, value, instance, schema) {
  if (!validator.isType(instance, 'object')) return;
  for (const [property, dependency] of Object.entries(value)) {
    if (!Object.prototype.hasOwnProperty.call(instance, property)) continue;
    if (Array.isArray(dependency)) {
      for (const each of dependency) {
        if (!Object.prototype.hasOwnProperty.call(instance, each)) {
          yield new ValidationError(
            `${JSON.stringify(each)} is a dependency of ${JSON.stringify(property)}`
          );
        }
      }
    } else {
      yield* validator.descend(instance, dependency, null);
    }
  }
}

export function* propertyNames(validator, value, instance, schema) {
  if (!validator.isType(instance, 'object')) return;
  for (const property of Object.keys(instance)) {
    if (!validator.isValidAgainst(property, value)) {
      yield new ValidationError(
        `${JSON.stringify(property)} does not match the propertyNames schema`
      );
    }
  }
}

export function* maxProperties(validator, value, instance, schema) {
  if (!validator.isType(instance, 'object')) return;
  if (Object.keys(instance).length > value) {
    yield new ValidationError(`${JSON.stringify(instance)} has too many properties`);
  }
}

export function* minProperties(validator, value, instance, schema) {
  if (!validator.isType(instance, 'object')) return;
  if (Object.keys(instance).length < value) {
    yield new ValidationError(`${JSON.stringify(instance)} does not have enough properties`);
  }
}

