"""Load jsonschema (and deps) from extracted PYZ marshalled code objects."""
import marshal, sys, os, types, importlib.abc, importlib.util

ROOT = '/tmp/pyzmods'
_loaded = {}

class PyzLoader(importlib.abc.MetaPathFinder, importlib.abc.Loader):
    PREFIXES = ('jsonschema', 'referencing', 'rpds', 'attr', 'attrs')

    def find_spec(self, fullname, path=None, target=None):
        if not fullname.startswith(self.PREFIXES):
            return None
        fn = os.path.join(ROOT, fullname.replace('.', '/') + '.code')
        is_pkg = False
        if not os.path.exists(fn):
            # package __init__ style? try directory
            if os.path.isdir(os.path.join(ROOT, fullname.replace('.', '/'))):
                return importlib.util.spec_from_loader(fullname, self, is_package=True)
            return None
        # a module with a matching directory is a package
        if os.path.isdir(os.path.join(ROOT, fullname.replace('.', '/'))):
            is_pkg = True
        return importlib.util.spec_from_loader(fullname, self, is_package=is_pkg)

    def create_module(self, spec):
        return None

    def exec_module(self, module):
        fn = os.path.join(ROOT, module.__name__.replace('.', '/') + '.code')
        if os.path.exists(fn):
            code = marshal.loads(open(fn, 'rb').read())
            exec(code, module.__dict__)

